        String propertyId=property.getString("id");JSONObject edit=args("qa_property_edit").put("property_id",propertyId).put("expected_record_hash",property.getString("record_hash")).put("updates",object().put("notes","QA Zugang nach Rücksprache").put("area_decimal",""));JSONObject updated=app.execute("update_property",edit).getJSONObject("record");yes(!updated.has("area_decimal"));rejected("WRITE_CONFLICT",()->app.execute("update_property",new JSONObject(edit.toString()).put("request_id","qa_property_stale").put("updates",object().put("name","QA stale"))));yes(app.query("get_property",object().put("property_id",propertyId)).getInt("history_total")==2);rejected("REVIER_REFERENCE_PROTECTED",()->app.protectParent("customer","qa_customer_1"));
