        JSONObject inquiry=app.execute("create_inquiry",args("qa_inquiry_create").put("customer_id","qa_customer_1").put("property_id",propertyId).put("title","QA Heckenanfrage").put("concern","QA Schnitt besichtigen").put("wish_from","2027-05-19").put("wish_until","2027-05-31")).getJSONObject("record");JSONObject inspect=args("qa_inspection_plan").put("inquiry_id",inquiry.getString("id")).put("expected_record_hash",inquiry.getString("record_hash")).put("starts_at","2027-05-19T08:00:00+02:00").put("ends_at","2027-05-19T08:45:00+02:00");JSONObject planned=app.execute("plan_inquiry_inspection",inspect);yes(planned.getString("external_calendar_status").equals("unknown"));yes(planned.getJSONObject("record").getString("status").equals("inspection_planned"));yes(app.execute("plan_inquiry_inspection",inspect).getBoolean("replayed")&&store.inspections==1);yes(store.snapshot.getJSONArray("appointments").length()==1);yes(store.snapshot.getJSONArray("appointments").getJSONObject(0).getString("purpose").equals("inspection"));
