        JSONArray ids=new JSONArray();for(int i=0;i<20;i++)ids.put(app.execute("plan_visit",args("qa_tour_visit_"+i).put("property_id",propertyId).put("title","QA Stopp "+i).put("date","2027-05-19").put("planned_minutes",10)).getString("visit_id"));JSONObject empty=app.query("get_day_tour",object().put("date","2027-05-19")).getJSONObject("record");JSONObject tour=app.execute("set_day_tour",args("qa_tour_set").put("date","2027-05-19").put("visit_ids",ids).put("expected_record_hash",empty.getString("record_hash"))).getJSONObject("record");JSONObject reordered=app.execute("move_tour_stop",args("qa_tour_move").put("date","2027-05-19").put("visit_id",ids.getString(1)).put("direction","up").put("expected_record_hash",tour.getString("record_hash"))).getJSONObject("record");yes(reordered.getJSONArray("visit_ids").getString(0).equals(ids.getString(1)));RevierApplicationService reopened=new RevierApplicationService(store,CLOCK);yes(reopened.query("get_day_tour",object().put("date","2027-05-19")).getJSONArray("stops").getJSONObject(0).getString("id").equals(ids.getString(1)));
