        long[] durations=new long[25];for(int i=0;i<durations.length;i++){long start=System.nanoTime();JSONObject hits=app.query("search_local",object().put("query","QA").put("limit",1));durations[i]=System.nanoTime()-start;yes(hits.getInt("total")>=750);}Arrays.sort(durations);double p95=durations[23]/1000000.0;System.out.println("MEASURE search300customers450properties warm25 p95_ms="+p95+" environment=hostJVM/syntheticMemoryPort noPixelClaim");yes(p95<300);
